```go
package shoppingcart

type Item struct {
    Name  string
    Price float64
}

type ShoppingCart struct {
    items []Item
}

func New() *ShoppingCart {
    return &ShoppingCart{
        items: make([]Item, 0),
    }
}

func (sc *ShoppingCart) AddItem(name string, price float64) {
    sc.items = append(sc.items, Item{Name: name, Price: price})
}

func (sc *ShoppingCart) GetTotal() float64 {
    total := 0.0
    for _, item := range sc.items {
        total += item.Price
    }
    return total
}

func (sc *ShoppingCart) GetItemCount() int {
    return len(sc.items)
}

func (sc *ShoppingCart) Clear() {
    sc.items = make([]Item, 0)
}

func (sc *ShoppingCart) RemoveItem(name string) bool {
    for i, item := range sc.items {
        if item.Name == name {
            sc.items = append(sc.items[:i], sc.items[i+1:]...)
            return true
        }
    }
    return false
}
```

